def decide(recipient_reputation, round_num, my_history):
    # Base threshold: more generous in early rounds, stricter later
    if round_num < 15:
        base_threshold = -0.1
    else:
        base_threshold = 0.3

    # Adjust threshold based on own donation rate (indirect: own behavior affects generosity)
    if len(my_history) > 0:
        donation_rate = sum(my_history) / len(my_history)
        if donation_rate > 0.6:
            # More forgiving if i donate often
            adjusted_threshold = base_threshold - 0.2
        else:
            # Become stricter if i seldom donate
            adjusted_threshold = base_threshold + 0.2
    else:
        adjusted_threshold = base_threshold

    # Clamp threshold to reasonable range
    threshold = max(-0.5, min(0.5, adjusted_threshold))
    return recipient_reputation > threshold
